{
  "gate_token": "gyqnmQ_-VcF1nCYhFHVcHQ",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined city.",
      "visual_description": "A windswept hilltop overlooking shattered spires at dusk; an ink-stained coated figure pins down a curling parchment with a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of every wrong turn.",
      "visual_description": "Close-up of an oil lamp with a single glowing eye inside its flame, hovering above the map, casting a long amber shadow.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox is wound up for scouting.",
      "visual_description": "Small clockwork fox with blue glass eyes, key-wind tail mid-turn, perched on a broken milestone marker.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver steps out of a roadside puddle mirror.",
      "visual_description": "A figure in a clear diving helmet emerges from a rain puddle, coat reflecting fractured city lights and crumbling towers.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They approach the cracked castle gates.",
      "visual_description": "Massive iron-bound gates split down the middle, vines crawling through; the four travelers cast small silhouettes against the looming stone.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Tattered royal banners flutter in the dead square.",
      "visual_description": "A plaza of shattered fountains, faded crimson banners hanging from broken poles; Tin Fox sniffs at a torn sigil on the ground.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "A frightened townsperson points toward the cursed tower.",
      "visual_description": "The sleeping tax collector slumps against a doorway, ledger pillow under his head, mumbling and gesturing limply at a leaning black spire.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The lamp hisses that the tower is a trap.",
      "visual_description": "The oracle lamp's flame-eye narrows toward a tower wreathed in violet smoke; Mara hesitates with compass raised.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Distant roars hint at something winged.",
      "visual_description": "Shadow of vast leathery wings sweeps across a rooftop; Tin Fox flattens its ears, blue eyes wide, on a tiled gable.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "An armored patrol marches the cobbled lane.",
      "visual_description": "From an alley shadow, the team watches plated boots and lantern poles pass; the Glass Diver's helmet catches a sliver of torchlight.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The Glass Diver slips through a stained-glass window.",
      "visual_description": "A figure dives headfirst into a tall cathedral window, body rippling through the colored panes like water without breaking them.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, a magic door pulses with runes.",
      "visual_description": "An archway carved with shifting silver glyphs in a moonlit hall; the oracle lamp floats close, illuminating the runes one by one.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Mara decodes the rune sequence from her maps.",
      "visual_description": "Mara crouched on marble tiles, parchments fanned around her, brass compass spinning wildly, Tin Fox holding down a corner with its paw.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector blocks the inner door.",
      "visual_description": "A round official snoring across a threshold, stamped papers stuck to his sleeves, the team trying to gently roll him aside.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "They find the captive behind a mirrored wall.",
      "visual_description": "The Glass Diver reaches a gloved hand through a tall mirror; the reflection shows the sleeping tax collector slumped in a gilded cell — the actual hostage.",
      "characters": ["glass_diver", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Alarms ring as the patrols close in.",
      "visual_description": "Red lanterns flare along corridor windows; Tin Fox sprints ahead, sparks flying from its wind-key, leading the others down a spiral stair.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the cracked river bridge.",
      "visual_description": "A long stone bridge over a black river at dawn; the four flee while masonry crumbles behind them, the oracle lamp swinging at Mara's belt.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far bank, Mara folds her map.",
      "visual_description": "Sunrise over reedy marsh; Mara tucking parchment into her coat, Tin Fox perched on her shoulder, the Glass Diver gazing back at the smoking skyline, the lamp dimmed to a sleepy ember beside the still-snoring official.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

